SELECT ?zone ?point ?ts WHERE {
  ?zone a brick:PerimeterBotZone ;
    brick:hasName ?name .
  FILTER(CONTAINS(str(?zone), "ZN_2"))
  ?point ref:isPartOf ?zone .
  ?point a brick:OccupancySensor .
  ?point ref:hasTimeseriesId ?ts .
}

SELECT ?zone ?name WHERE {
  ?zone a brick:PerimeterBotZone .
  OPTIONAL {?zone brick:hasName ?name}
}

SELECT ?point ?class ?ts WHERE {
  ?point a brick:OccupancySensor .
  ?point ?p ?class .
  FILTER(?p = a && str(?class) LIKE "brick:Occupancy%")
  OPTIONAL{?point ref:hasTimeseriesId ?ts}
}

SELECT ?zone WHERE {
  ?zone a brick:PerimeterBotZone .
}

SELECT ?point WHERE {
  ?point a brick:OccupancySensor .
}

SELECT ?class (COUNT(*) AS ?n) WHERE {
  ?p a ?class .
} GROUP BY ?class ORDER BY DESC(?n) LIMIT 60

SELECT ?point ?loc WHERE {
  ?point a brick:Occupancy_Sensor .
  ?point brick:hasSubComponent ?loc .
} LIMIT 20

SELECT ?point ?loc WHERE {
  ?point a brick:Occupancy_Sensor .
  ?loc brick:hasSubComponent ?point .
} LIMIT 20

SELECT ?o ?type ?value WHERE {
  ?point a brick:Occupancy_Sensor .
  ?point ?o ?type .
} LIMIT 30

SELECT ?z WHERE {
  ?z ?o ?v .
  FILTER(CONTAINS(str(?z), "Perimeter_bot"))
} LIMIT 20

SELECT ?z WHERE {
  ?z ?o ?v .
  FILTER(CONTAINS(str(?z), "ZN_2"))
} LIMIT 20

SELECT ?z ?name WHERE {
  ?z brick:hasName ?name .
} LIMIT 40

SELECT ?z WHERE {
  ?z a brick:HVAC_Zone .
} LIMIT 30

SELECT ?room ?o ?v WHERE {
  ?room a brick:Room .
  ?room ?o ?v .
} LIMIT 20

SELECT ?room ?label WHERE {
  ?room a brick:Room ; rdfs:label ?label .
  FILTER(CONTAINS(?label, "Perimeter_bot_ZN_2 "))
}

SELECT ?room ?label ?point WHERE {
  ?room a brick:Room ; rdfs:label ?label .
  FILTER(CONTAINS(?label, "Perimeter_bot_ZN_2 "))
  ?point a brick:Occupancy_Sensor .
  ?point brick:hasLocation ?room .
  OPTIONAL{?point ref:hasExternalReference ?ts}
}

SELECT ?room ?label ?point ?ts WHERE {
  ?room a brick:Room ; rdfs:label ?label .
  FILTER(CONTAINS(?label, "Perimeter_bot_ZN_2 "))
  ?point a brick:Occupancy_Sensor .
  ?point brick:hasLocation ?room .
